replacements.new_str:
        .sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tax_rounds_up_above_half_a_cent() {
        assert_eq!(tax_cents(1999, 825), 165);
        assert_eq!(total_cents(1999, 825), 2164);
    }

    #[test]
    fn tax_rounds_down_below_half_a_cent() {
        assert_eq!(tax_cents(1001, 100), 10);
    }

    #[test]
    fn tax_is_exact_on_whole_cents() {
        assert_eq!(tax_cents(2000, 500), 100);
    }

    #[test]
    fn receipt_summary_matches_processor() {
        assert_eq!(receipt::summary(1999, 825), ["Subtotal  $19.99", "Tax       $1.65", "Total     $21.64"]);
    }
}
